func Authenticate(r *http.Request, v KeyValidator, wantScope string) (string, error) {
	tok := BearerToken(r)
	if tok == "" {
		return "", ErrUnauthorized
	}
	userID, scopes, err := v.ValidateKey(r.Context(), tok)
	if err != nil {
		return "", ErrUnauthorized
	}
	if wantScope != "" && !HasScope(scopes, wantScope) {
		return "", ErrForbidden
	}
	return userID, nil
}
